"""
    get_where_clause returns the where clause from the given query list.
    :param columns_to_query_lst: columns for where clause.
    :return:
    """
def get_where_clause(columns_to_query_lst: Any) -> object {
    where_str = "where ";
    equals_str = [];
    for row in columns_to_query_lst {
        temp_str = "c." + row + " = t." + row;
        equals_str.append(temp_str);
    }
    joined_str = " AND ".join(equals_str);
    where_str = where_str + joined_str;
    return where_str;
}

"""
    Parse a tuple string like "(1024;768)" and return strings of the elements
    """
def tuple_get(string: Any, count: Any = None) -> object {
    if not string {
        return None;
    }
    string = string.strip();
    assert (string.startswith("(") and string.endswith(")"));
    string = string[1:-1];
    res = [x.strip() for x in string.split(";")];
    if (count is not None) {
        assert (len(res) == count);
    }
    return res;
}

"""
    Generate a list of counts for each item in the input list. Outputs with highest counted item at index 0

    Args:
        items (list): A list of objects to be sorted

    Returns:
        list: A list of unique items in the input and the number of occurances for each item
    """
def count(items: list) -> list {
    def row2(k: Any) -> object {
        return k[1];
    }
    if isinstance(items[0], `list) {
        items = [`tuple(x) for x in items];
    }
    uniqs = [[x, items.count(x)] for x in `set(items)];
    uniqs.sort(key=row2, reverse=True);
    return uniqs;
}

"""
    Read a string until a null is encountered

    returns (string up to null , remainder after null)
    """
def readUntilNull(s: Any) -> object {
    item = s.split(b'\x00', 1);
    if (len(item) == 1) {
        return (item[0], None);
    } else {
        return (item[0], item[1]);
    }
}

